import com.cowave.search.client.proxy_api.ProxyApiClient
import com.cowave.search.domain.proxy.mall.Mall
import com.cowave.search.domain.proxy.mall.MallRepository
import org.springframework.stereotype.Component
import kotlin.jvm.java
import kotlin.text.trimIndent
import kotlin.to

@Component
class MallRepositoryImpl(
    private val client: ProxyApiClient,
) : MallRepository {
    override fun findAllByIds(mallIds: List<Int>): List<Mall> {
        val query =
            """
            query GetMalls(${'$'}ids: [Int!]) {
                malls(input: {  ids: ${'$'}ids }) {
                    items {
                        mallId
                        mallUseYnDanawa
                        mallUseYnEnuri
                    }
                }
            }
            """.trimIndent()

        return client.query(
            query = query,
            variables = mapOf("ids" to mallIds),
            retrievePath = "malls.items",
            Mall::class.java,
        )
    }
}

