package com.cowave.search.outbound_adapter.proxy

import com.cowave.search.domain.proxy.category.Category
import com.cowave.search.domain.proxy.category.CategoryHierarchyResolver
import com.cowave.search.domain.proxy.category.CategoryRepository
import com.cowave.shared.utils.logger
import com.fasterxml.jackson.databind.ObjectMapper
import org.springframework.beans.factory.annotation.Value
import org.springframework.data.redis.core.RedisTemplate
import org.springframework.stereotype.Component
import java.time.Duration
import java.util.concurrent.ConcurrentHashMap

@Component
class CachingCategoryHierarchyResolver(
    private val categoryRepository: CategoryRepository,
    private val redisTemplate: RedisTemplate<String, String>,
    private val objectMapper: ObjectMapper,
    @Value("\${cache.category.l1-max-size:10000}")
    private val l1MaxSize: Int,
    @Value("\${cache.category.l1-ttl-seconds:300}")
    private val l1TtlSeconds: Long,
    @Value("\${cache.category.l2-ttl-seconds:3600}")
    private val l2TtlSeconds: Long,
    @Value("\${cache.category.l2-key-prefix:category:hierarchy:}")
    private val l2KeyPrefix: String,
) : CategoryHierarchyResolver {
    private val logger by logger()

    private val l1Cache = ConcurrentHashMap<Int, L1Entry>()

    override fun resolve(categoryIds: List<Int>): Map<Int, Category> {
        if (categoryIds.isEmpty()) return emptyMap()

        val result = mutableMapOf<Int, Category>()
        val l1MissIds = mutableListOf<Int>()

        // L1 캐시 조회
        for (id in categoryIds) {
            val entry = l1Cache[id]
            if (entry != null && !entry.isExpired()) {
                result[id] = entry.category
            } else {
                if (entry != null) l1Cache.remove(id)
                l1MissIds.add(id)
            }
        }

        if (l1MissIds.isEmpty()) return result

        val l2MissIds = mutableListOf<Int>()

        // L2 캐시(Valkey) 조회
        try {
            val keys = l1MissIds.map { "$l2KeyPrefix$it" }
            val values = redisTemplate.opsForValue().multiGet(keys)
            if (values != null) {
                for (i in l1MissIds.indices) {
                    val json = values[i]
                    if (json != null) {
                        val category = objectMapper.readValue(json, Category::class.java)
                        result[l1MissIds[i]] = category
                        putL1(l1MissIds[i], category)
                    } else {
                        l2MissIds.add(l1MissIds[i])
                    }
                }
            } else {
                l2MissIds.addAll(l1MissIds)
            }
        } catch (ex: Exception) {
            logger.warn { "Valkey 카테고리 캐시 조회 실패, API로 폴백: $ex" }
            l2MissIds.addAll(l1MissIds)
        }

        if (l2MissIds.isEmpty()) return result

        // L3: Proxy API 호출
        val categories = categoryRepository.findAllByIds(l2MissIds)
        for (category in categories) {
            result[category.id] = category
            putL1(category.id, category)
            putL2(category.id, category)
        }

        return result
    }

    private fun putL1(
        id: Int,
        category: Category,
    ) {
        if (l1Cache.size >= l1MaxSize) {
            evictExpiredL1Entries()
        }
        l1Cache[id] = L1Entry(category, System.currentTimeMillis() + l1TtlSeconds * 1000)
    }

    private fun putL2(
        id: Int,
        category: Category,
    ) {
        try {
            val json = objectMapper.writeValueAsString(category)
            redisTemplate.opsForValue().set(
                "$l2KeyPrefix$id",
                json,
                Duration.ofSeconds(l2TtlSeconds),
            )
        } catch (ex: Exception) {
            logger.warn { "Valkey 카테고리 캐시 저장 실패 [id=$id]: $ex" }
        }
    }

    private fun evictExpiredL1Entries() {
        val now = System.currentTimeMillis()
        val iterator = l1Cache.entries.iterator()
        while (iterator.hasNext()) {
            val entry = iterator.next()
            if (entry.value.expireAt <= now) {
                iterator.remove()
            }
        }
    }

    private data class L1Entry(
        val category: Category,
        val expireAt: Long,
    ) {
        fun isExpired(): Boolean = System.currentTimeMillis() > expireAt
    }
}

